import os
import sqlite3
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/app/data/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        password_hash TEXT,
        email TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various criteria. Supports partial matching."""
    search_field = request.args.get('field', 'username')
    search_value = request.args.get('q', '')
    include_inactive = request.args.get('include_inactive', 'false')

    # Validate field name against allowed columns
    allowed_fields = ['username', 'email', 'role']
    if search_field not in allowed_fields:
        return jsonify({'error': 'Invalid search field'}), 400

    # Log the search action
    db = get_db()
    log_query = f"INSERT INTO audit_log (action, details) VALUES ('search', 'field={search_field}, q={search_value}')"
    try:
        db.execute(log_query)
        db.commit()
    except sqlite3.Error:
        pass  # Non-critical, continue with search

    # Build search query - field is validated above so safe to interpolate
    query = f"SELECT id, username, email, role FROM users WHERE {search_field} LIKE ?"
    if include_inactive != 'true':
        query += " AND role != 'inactive'"

    try:
        cursor = db.execute(query, (f'%{search_value}%',))
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'results': results, 'count': len(results)})
    except sqlite3.Error as e:
        return jsonify({'error': 'Search failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user details by ID."""
    db = get_db()
    cursor = db.execute('SELECT id, username, email, role FROM users WHERE id = ?', (user_id,))
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'User not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create a new user."""
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing required fields'}), 400

    password_hash = hashlib.sha256(data['password'].encode()).hexdigest()
    api_key = os.urandom(32).hex()

    db = get_db()
    try:
        db.execute(
            'INSERT INTO users (username, password_hash, email, role, api_key) VALUES (?, ?, ?, ?, ?)',
            (data['username'], password_hash, data.get('email', ''), data.get('role', 'user'), api_key)
        )
        db.commit()
        return jsonify({'message': 'User created', 'api_key': api_key}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
